import {libraryMarkup,mountLibrary} from './library3d.js';
import {createGardenAudio} from './garden-audio.js';
const paths={leaf:'M20 4C8 2 3 8 5 16c8 5 16-1 15-12Z M5 20 16 9',book:'M3 4c4-1 7 0 9 2 2-2 5-3 9-2v15c-4-1-7 0-9 2-2-2-5-3-9-2Z M12 6v15',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',bookmark:'M6 3h12v18l-6-4-6 4Z',note:'M14 3H4v18h16V10 M14 3v7h6 M8 14h8 M8 17h5',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',arrow:'M4 12h16 m-6-6 6 6-6 6',back:'M20 12H4m6-6-6 6 6 6',chevron:'m9 5 7 7-7 7',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M3 12h18 M12 3c-5 5-5 13 0 18 5-5 5-13 0-18',landmark:'m3 8 9-5 9 5Z M5 10v8m5-8v8m4-8v8m5-8v8M3 21h18',chart:'M4 3v17h17 M8 14l4-5 4 3 5-7',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M19 5l-2 2M7 17l-2 2',sprout:'M12 21V11 M12 15C3 15 3 7 3 7s9-1 9 8 M12 11C12 2 21 3 21 3s0 8-9 8',heart:'M20 5c-4-4-8 1-8 1s-4-5-8-1c-5 5 8 15 8 15s13-10 8-15Z',share:'M16 5 8 10m0 4 8 5 M7 8a3 3 0 1 0 0 6 3 3 0 0 0 0-6 M18 2a3 3 0 1 0 0 6 3 3 0 0 0 0-6 M18 16a3 3 0 1 0 0 6 3 3 0 0 0 0-6',close:'m6 6 12 12M6 18 18 6',shuffle:'M3 5h3l12 14h3M17 15l4 4-4 3M3 19h3l4-5m4-5 4-4h3m-4-3 4 3-4 4',list:'M8 5h13M8 12h13M8 19h13M3 5h1M3 12h1M3 19h1',walk:'M13 3h.01M10 8l4-1 3 5 4 1M7 12l3-4-1 8-4 5m4-5 6 1 2 5',check:'m5 12 4 4L20 5',external:'M14 3h7v7m0-7L10 14M10 3H3v18h18v-7',download:'M12 3v12m-5-5 5 5 5-5M3 16v5h18v-5',settings:'M12 3v4m0 10v4M3 12h4m10 0h4 M6 6l3 3m6 6 3 3M18 6l-3 3m-6 6-3 3',up:'m6 14 6-6 6 6',down:'m6 10 6 6 6-6'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[name]||paths.book}"/></svg>`;
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL=url=>{try{return new URL(url).protocol==='https:'?escape(url):'#';}catch{return '#';}};
let data, view='library', activeSection='', mode='walk', search='', collectionsTab='saved';
let roomController=null;let shellCleanup=()=>{};const gardenAudio=createGardenAudio(window);const roomPose={x:0,z:6.2,yaw:0};
let state={saved:[],liked:[],notes:{},visited:[],learned:0,archive:{}};
try{const s=JSON.parse(localStorage.getItem('garden-v1'));if(s&&Array.isArray(s.saved)&&Array.isArray(s.liked)&&s.notes&&Array.isArray(s.visited))state={...state,...s};}catch{}
function persist(){try{localStorage.setItem('garden-v1',JSON.stringify(state));}catch{toast('Browser storage is unavailable. Your changes will last for this visit.');}}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3500);}
const getCard=id=>data.cards.find(c=>c.id===id)||state.archive?.[id];
const section=id=>data.sections.find(s=>s.id===id);
const date=value=>new Date(value).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});
const shortDate=value=>new Date(value).toLocaleDateString(undefined,{month:'short',day:'numeric'});
function nav(label,target,i,count){return `<button class="nav-item ${view===target?'selected':''}" data-view="${target}">${icon(i)}<span>${label}</span>${count?`<span class="count">${count}</span>`:''}</button>`;}
function shell(content){shellCleanup();roomController?.dispose();roomController=null;document.querySelector('#app').innerHTML=`<button class="corner-menu-edge" aria-label="Open navigation" aria-controls="garden-sidebar" aria-expanded="false"></button><button class="menu-scrim" aria-label="Close navigation" hidden></button><aside class="sidebar" id="garden-sidebar" inert aria-hidden="true"><button class="sidebar-close" aria-label="Close navigation">×</button><a href="#" class="brand" data-toggle-menu><span class="brand-icon">${icon('sprout')}</span><span>The Garden<small>A LIBRARY FOR THE CURIOUS</small></span></a><p class="nav-label">YOUR LITTLE CORNER</p><nav aria-label="Main">${nav('Explore the library','library','book')}${nav('Saved reads','saved','bookmark',state.saved.length)}${nav('My notes','notes','note',Object.keys(state.notes).length)}</nav><div class="sidebar-shelves"><p class="nav-label">THE SHELVES</p>${data.sections.map(s=>`<button data-section="${s.id}" class="shelf-nav ${activeSection===s.id&&view==='feed'?'active':''}"><span class="dot" style="background:${s.color}"></span>${escape(s.name)}${s.live?'<span class="tiny-dot"></span>':''}</button>`).join('')}</div><div class="sidebar-bottom"><div class="quiet-card">${icon('leaf')}<p>A few minutes.<br>A little more perspective.</p><span>Let curiosity lead the way.</span></div><button class="source-link" data-action="sources">${icon('globe')} Our sources & approach ${icon('external')}</button><div class="visitor"><span class="visitor-avatar">${icon('sprout')}</span><span>Your growing collection<small>Saved on this device</small></span></div></div></aside><div class="workspace"><header class="topbar"><button class="garden-menu-trigger" aria-label="Open The Garden menu" aria-expanded="false" aria-controls="garden-sidebar">${icon('sprout')}<span>The Garden</span><small>☰</small></button><span class="breadcrumb">The Garden <span>/</span> ${view==='feed'?escape(section(activeSection).name):view==='library'?'The garden':view==='notes'?'My notes':'Saved reads'}</span><div class="topbar-right"><span class="no-rush">${icon('sun')} A good day to learn something.</span><button class="round" data-action="settings" aria-label="Reading preferences">${icon('settings')}</button><span class="avatar">You</span></div></header><main id="main" tabindex="-1">${content}</main><footer><span>${icon('sprout')} A little learning goes a long way.</span><button data-action="sources">Thoughtfully sourced. Always curious. ${icon('external')}</button></footer></div><nav class="mobile-nav" aria-label="Mobile navigation">${nav('Explore','library','book')}${nav('Saved','saved','bookmark')}${nav('Notes','notes','note')}</nav>`;bind();}
function hero(){return libraryMarkup(data.sections);}
const plural=(count,singular,pluralForm=singular+'s')=>`${count} ${count===1?singular:pluralForm}`;
function shelfCard(s){const count=data.cards.filter(c=>c.section===s.id).length;return `<button class="section-card" data-section="${s.id}"><div class="section-art art-${s.id}" style="--shelf-color:${s.color}"><span class="art-icon">${icon(s.icon)}</span><div class="book-spines">${Array.from({length:10},(_,i)=>`<i style="--i:${i};height:${40+((i*17)%36)}px"></i>`).join('')}</div></div><div class="section-info"><small>${escape(s.zone)}</small><h3>${escape(s.name)}</h3><p>${escape(s.description)}</p><span>${s.live?'Source snapshots':plural(count,'short read')}<b>${icon('arrow')}</b></span></div></button>`;}
function library(){const filtered=data.sections.filter(s=>(s.name+' '+s.description).toLowerCase().includes(search.toLowerCase()));shell(`<div class="page-heading"><div><span class="eyebrow">WANDER. WONDER. GROW.</span><h1>A little wiser, one shelf at a time<span>.</span></h1><p>An open-air garden of ideas. Follow the winding shelves and see what blooms.</p></div><button class="button outline surprise" data-action="surprise">${icon('shuffle')} Surprise me</button></div><div class="library-toolbar"><div class="segmented" aria-label="Library view"><button class="${mode==='walk'?'on':''}" data-mode="walk">${icon('walk')} Wander the garden</button><button class="${mode==='list'?'on':''}" data-mode="list">${icon('list')} Shelf view</button></div><label class="search-input">${icon('search')}<input id="shelf-search" placeholder="Find a little inspiration…" aria-label="Search shelves" value="${escape(search)}"><kbd>/</kbd></label></div>${mode==='walk'&&!search?`<div class="experience-grid">${hero()}<aside class="discovery-panel"><span class="eyebrow">A SMALL THING TO KNOW</span><div class="daily-illustration"><div class="orbit"></div><div class="sun-disc"></div><div class="plant-stem"></div><div class="plant-leaf l1"></div><div class="plant-leaf l2"></div><div class="plant-leaf l3"></div><div class="plant-leaf l4"></div><div class="plant-pot"></div><div class="illus-book b1"></div><div class="illus-book b2"></div><span>GROW AT YOUR OWN PACE</span></div><span class="pill">${icon('landmark')} African History</span><h3>A continent of stories.<br>A good place to begin.</h3><p>Kingdoms, connections, and ideas that travelled far beyond their borders.</p><button class="text-button" data-section="history">Explore this shelf ${icon('arrow')}</button><div class="panel-bottom">${icon('book')} Just a minute. A new perspective.</div></aside></div>`:''}${mode==='list'||search?`<div class="section-heading"><div><span class="eyebrow">SIX SHELVES. ENDLESS CONNECTIONS.</span><h2>${search?'Find your next discovery':'Follow a thread of curiosity'}</h2></div><span class="muted">Pick a place. Let it teach you.</span></div><div class="section-grid">${filtered.map(shelfCard).join('')||'<div class="empty"><h3>No shelves found</h3><p>Try “history”, “news”, or “money”.</p></div>'}</div>`:''}<div class="gentle-banner">${icon('leaf')}<div><h3>Leave with something, not just more screen time.</h3><p>A few small ideas are enough for today. The shelves will be here tomorrow.</p></div><span>Stay curious.</span></div>`);}
function card(c){const s=section(c.section);const note=state.notes[c.id];const expired=s.live&&Date.now()-Date.parse(c.asOf)>86400000;return `<article class="read-card" id="card-${escape(c.id)}"><div class="card-source"><span class="source-mark" style="--source-color:${s.color}">${icon(c.source==='FRED'?'chart':s.icon)}</span><div><strong>${escape(c.source)}</strong><small>${escape(s.name)} <span>·</span> ${shortDate(c.asOf)}</small></div><span class="read-time">${expired?'Older snapshot':'1 min read'}</span></div>${c.image?`<img class="card-image" src="${safeURL(c.image)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:''}<button class="headline-button" data-detail="${escape(c.id)}"><h2>${escape(c.title)}</h2></button>${c.value?`<div class="quote-value">${escape(c.value)}<span>%</span></div><p>Monthly effective federal funds rate. Observation: ${date(c.period)}. Historical data, not a real-time quote.</p>`:`<p>${escape(c.text)}</p>`}<a class="attribution" href="${safeURL(c.url)}" target="_blank" rel="noopener noreferrer">${icon('external')} ${escape(c.source)} <span>· As of ${date(c.asOf)}</span></a>${note?`<button class="attached-note" data-note="${escape(c.id)}">${icon('note')}<span>${escape(note.text)}</span>${icon('chevron')}</button>`:''}<div class="card-actions"><button class="${state.liked.includes(c.id)?'is-active':''}" data-like="${escape(c.id)}" aria-pressed="${state.liked.includes(c.id)}" aria-label="Like ${escape(c.title)}">${icon('heart')}<span>${state.liked.includes(c.id)?'Liked':'Like'}</span></button><button class="${state.saved.includes(c.id)?'is-active':''}" data-save="${escape(c.id)}" aria-pressed="${state.saved.includes(c.id)}">${icon('bookmark')}<span>${state.saved.includes(c.id)?'Saved':'Save'}</span></button><button data-note="${escape(c.id)}">${icon('note')}<span>${note?'Edit note':'Add a note'}</span></button><button data-share="${escape(c.id)}" aria-label="Share ${escape(c.title)}">${icon('share')}</button></div></article>`;}
function feed(){const s=section(activeSection);const cards=data.cards.filter(c=>c.section===s.id);shell(`<button class="back-button" data-view="library">${icon('back')} Back to the library</button><div class="feed-layout"><section><div class="feed-heading"><span class="eyebrow">${escape(s.zone)}</span><h1>${escape(s.name)}<span>.</span></h1><p>${escape(s.description)}</p><div class="feed-meta"><span>${icon('book')} ${plural(cards.length,'short read')}</span><span>${s.live?'Snapshot updated':'Sourced'} ${date(data.generatedAt)}</span></div>${s.live?'<div class="snapshot-notice">Source snapshot · Updates appear when the source pipeline publishes a new snapshot. Market data may be delayed.</div>':''}</div><div class="feed-cards">${cards.map(card).join('')||'<div class="empty"><h2>A quiet shelf for now.</h2><p>Its source is unavailable. Explore another shelf while it refreshes.</p></div>'}</div><div class="feed-end">${icon('sprout')}<span class="eyebrow">A GOOD PLACE TO PAUSE</span><h2>A little more than you came with.</h2><p>You’ve reached the end of this shelf. Let an idea settle, or follow a new thread.</p><button class="button primary" data-action="learned">${icon('check')} I learned something</button><button class="text-button" data-action="surprise">Wander somewhere new ${icon('arrow')}</button></div></section><aside class="feed-aside"><div class="notebook-teaser"><span class="eyebrow">MAKE IT YOUR OWN</span>${icon('note')}<h3>A thought worth keeping?</h3><p>Add a private note to any read. Your connections, questions, and little lightbulb moments belong here.</p><span>Just for you. Saved on this device.</span></div><h3>A neighbouring shelf</h3>${data.sections.filter(t=>t.id!==s.id).slice(0,2).map(shelfCard).join('')}</aside></div>`);}
function collection(){let cards=[...data.cards,...Object.values(state.archive||{}).filter(c=>!data.cards.some(d=>d.id===c.id))].filter(c=>view==='saved'?state.saved.includes(c.id):state.notes[c.id]);if(search)cards=cards.filter(c=>(c.title+' '+(state.notes[c.id]?.text||'')+' '+section(c.section).name).toLowerCase().includes(search.toLowerCase()));shell(`<div class="page-heading"><div><span class="eyebrow">YOUR GROWING COLLECTION</span><h1>${view==='notes'?'Thoughts worth keeping':'For another quiet moment'}<span>.</span></h1><p>${view==='notes'?'Your questions, connections, and little lightbulb moments. Private, and just for you.':'A place for the reads you want to come back to.'}</p></div>${view==='notes'?`<button class="button outline" data-action="export">${icon('download')} Export notes</button>`:''}</div><div class="collection-tools"><label class="search-input">${icon('search')}<input id="collection-search" aria-label="Search your collection" placeholder="Search ${view==='notes'?'your notes':'saved reads'}…" value="${escape(search)}"></label><span class="muted">${plural(cards.length,view==='notes'?'note':'read')} · stored on this device</span></div><div class="collection-content">${cards.length?data.sections.map(s=>{const group=cards.filter(c=>c.section===s.id);return group.length?`<h2 class="collection-group">${icon(s.icon)} ${escape(s.name)}</h2>${group.map(card).join('')}`:'';}).join(''):`<div class="empty">${icon(view==='notes'?'note':'bookmark')}<h2>${search?'No matches yet.':view==='notes'?'Every idea starts with a little thought.':'Something will catch your eye.'}</h2><p>${search?'Try another word.':view==='notes'?'Tap “Add a note” on a read to make it your own.':'Save a read from any shelf and find it here.'}</p><button class="button primary" data-view="library">Explore the library ${icon('arrow')}</button></div>`}</div>`);}
function render(){if(view==='library')library();else if(view==='feed')feed();else collection();}
function openSection(id){if(!section(id))return;activeSection=id;view='feed';search='';if(!state.visited.includes(id)){state.visited.push(id);persist();}render();window.scrollTo({top:0,behavior:'instant'});}
function openModal(html){const modal=document.querySelector('#modal');modal.innerHTML=`<button class="modal-close round" aria-label="Close dialog">${icon('close')}</button>${html}`;modal.querySelector('.modal-close').onclick=()=>modal.close();modal.onclick=e=>{if(e.target===modal)modal.close();};modal.showModal();}
function noteEditor(id){const c=getCard(id);openModal(`<span class="eyebrow">A THOUGHT OF YOUR OWN</span><h2>${escape(c.title)}</h2><p class="muted">Only you can see this. Saved in this browser.</p><form id="note-form"><label for="note-text">Your private note</label><textarea id="note-text" maxlength="5000" placeholder="What stayed with you? A connection, a question, an idea…">${escape(state.notes[id]?.text||'')}</textarea><div class="form-bottom">${state.notes[id]?'<button type="button" class="delete-note" id="delete-note">Delete note</button>':'<span class="muted">Make a little room for your thoughts.</span>'}<button class="button primary" type="submit">${icon('check')} Save note</button></div></form>`);document.querySelector('#note-form').onsubmit=e=>{e.preventDefault();const text=document.querySelector('#note-text').value.trim();if(!text){toast('Write a thought before saving.');return;}state.archive??={};state.archive[id]=c;state.notes[id]={text,updatedAt:new Date().toISOString()};persist();document.querySelector('#modal').close();render();toast('A thought worth keeping. Note saved.');};document.querySelector('#delete-note')?.addEventListener('click',()=>{delete state.notes[id];persist();document.querySelector('#modal').close();render();toast('Note deleted.');});}
function sourceInfo(){openModal(`<span class="eyebrow">KNOW WHERE IT COMES FROM</span><h2>Curiosity, with a source.</h2><p>Every read links to its original source. These are source excerpts, not independent reporting. Check the original for full context.</p><div class="source-list"><h3>Wikipedia</h3><p>Background and history from the Wikipedia REST API. Text is attributed to Wikipedia contributors under CC BY-SA 4.0. Follow each source link for authors, revisions, and image licences.</p><h3>The Guardian</h3><p>Headlines and short excerpts from its World News RSS feed. Full reporting belongs to The Guardian; follow the original link.</p><h3>FRED</h3><p>Historical federal funds rate observations from the Federal Reserve Bank of St. Louis, supplied by the Board of Governors of the Federal Reserve System. Values are preserved exactly; observations are monthly and delayed.</p></div><p class="muted">This version uses a source snapshot from ${date(data.generatedAt)}. A scheduled ingestion workflow is included in the source code; continuous publishing must be enabled separately. Failed sources are omitted. Personal notes, likes, and saves stay in your browser. No sign-up, analytics trackers, or investment advice.</p><p class="muted">Library photograph: Unsplash. Background text: <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener noreferrer">CC BY-SA 4.0</a>.</p>`);}
function bind(){
 const trigger=document.querySelector('.garden-menu-trigger'),sidebar=document.querySelector('.sidebar'),scrim=document.querySelector('.menu-scrim');
 let closeTimer;const setMenu=open=>{clearTimeout(closeTimer);document.body.classList.toggle('menu-open',open);trigger.setAttribute('aria-expanded',String(open));document.querySelector('.corner-menu-edge').setAttribute('aria-expanded',String(open));sidebar.inert=!open;sidebar.setAttribute('aria-hidden',String(!open));scrim.hidden=!open;};
 document.querySelector('.corner-menu-edge').onclick=()=>setMenu(true);document.querySelector('.corner-menu-edge').onpointerenter=e=>{if(e.pointerType!=='touch')setMenu(true);};
 trigger.onclick=()=>setMenu(!document.body.classList.contains('menu-open'));
 trigger.onpointerenter=e=>{if(e.pointerType!=='touch')setMenu(true);};
 sidebar.onpointerenter=()=>clearTimeout(closeTimer);sidebar.onpointerleave=e=>{if(e.pointerType!=='touch')closeTimer=setTimeout(()=>{if(!sidebar.contains(document.activeElement))setMenu(false);},250);};
 document.querySelector('[data-toggle-menu]').onclick=e=>{e.preventDefault();setMenu(false);};scrim.onclick=()=>setMenu(false);document.querySelector('.sidebar-close').onclick=()=>{setMenu(false);trigger.focus({preventScroll:true});};
 const onMenuKey=e=>{if(e.key==='Escape'&&document.body.classList.contains('menu-open')){setMenu(false);trigger.focus({preventScroll:true});}};document.addEventListener('keydown',onMenuKey);shellCleanup=()=>{clearTimeout(closeTimer);document.removeEventListener('keydown',onMenuKey);document.body.classList.remove('menu-open');};
 const sound=document.querySelector('.garden-sound'),volume=document.querySelector('.garden-volume');
 if(sound){sound.setAttribute('aria-pressed',String(gardenAudio.enabled));sound.textContent=gardenAudio.enabled?'♫ Garden sounds on':'♫ Garden sounds';sound.onclick=async()=>{try{if(gardenAudio.enabled)await gardenAudio.stop();else await gardenAudio.start();sound.setAttribute('aria-pressed',String(gardenAudio.enabled));sound.textContent=gardenAudio.enabled?'♫ Garden sounds on':'♫ Garden sounds';}catch(e){toast(e.message);}};volume.value=String(gardenAudio.volume);volume.oninput=()=>gardenAudio.setVolume(volume.value);}

 document.querySelectorAll('[data-view]').forEach(b=>b.onclick=e=>{e.preventDefault();view=b.dataset.view;activeSection='';search='';render();window.scrollTo(0,0);});
 document.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>openSection(b.dataset.section));
 document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;render();});
 const room=document.querySelector('.library-room');if(!room&&gardenAudio.enabled)gardenAudio.stop();if(room)roomController=mountLibrary(room,{sections:data.sections,onSelect:openSection,pose:roomPose});
 const searchInput=document.querySelector('#shelf-search,#collection-search');if(searchInput)searchInput.oninput=e=>{const pos=e.target.selectionStart;const id=e.target.id;search=e.target.value;render();const input=document.getElementById(id);input.focus();input.setSelectionRange(pos,pos);};
 for(const kind of ['save','like'])document.querySelectorAll(`[data-${kind}]`).forEach(b=>b.onclick=()=>{const key=kind==='save'?'saved':'liked';const id=b.dataset[kind];const has=state[key].includes(id);if(kind==='save'&&!has){state.archive??={};state.archive[id]=getCard(id);}state[key]=has?state[key].filter(x=>x!==id):[...state[key],id];persist();const y=window.scrollY;render();window.scrollTo(0,y);if(kind==='save')toast(has?'Removed from saved reads.':'Saved for another quiet moment.');});
 document.querySelectorAll('[data-note]').forEach(b=>b.onclick=()=>noteEditor(b.dataset.note));
 document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{const c=getCard(b.dataset.detail);openModal(`<span class="eyebrow">${escape(section(c.section).name)}</span><h2>${escape(c.title)}</h2><p>${escape(c.raw.length<12000?c.raw:c.text)}</p><p class="muted">${escape(c.source)} · Retrieved ${date(c.asOf)} · ${escape(c.license)}</p><a class="button primary" href="${safeURL(c.url)}" target="_blank" rel="noopener noreferrer">Read the original ${icon('external')}</a>`);});
 document.querySelectorAll('[data-share]').forEach(b=>b.onclick=async()=>{const c=getCard(b.dataset.share);try{if(navigator.share)await navigator.share({title:c.title,text:c.title,url:c.url});else{await navigator.clipboard.writeText(c.url);toast('Source link copied. Your private notes stay private.');}}catch(e){if(e.name!=='AbortError')toast('Could not share. Open the source link to copy it.');}});
 document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{switch(b.dataset.action){case 'surprise':{const options=data.sections.filter(s=>s.id!==activeSection);const id=options[Math.floor(Math.random()*options.length)].id;if(view==='library'&&roomController)roomController.walkTo(id);else openSection(id);break;}case 'sources':sourceInfo();break;case 'learned':state.learned++;persist();b.innerHTML=icon('check')+' A little wiser. Take it with you.';b.disabled=true;toast('A little learning goes a long way.');break;case 'settings':openModal(`<span class="eyebrow">YOUR PACE, YOUR PLACE</span><h2>Make yourself comfortable.</h2><div class="preference"><label for="reduce-motion">Reduce motion</label><input id="reduce-motion" type="checkbox" ${document.documentElement.classList.contains('reduce-motion')?'checked':''}></div><p class="muted">Use W A S D or the on-screen arrows to move, drag to look, and Enter to open a nearby shelf. Reduce motion turns off automatic walking; Shelf view lets you browse without moving.</p><p class="muted">Your notes and saved reads are stored on this device. Export your notes to keep a backup before clearing browser data.</p>`);document.querySelector('#reduce-motion').onchange=e=>{document.documentElement.classList.toggle('reduce-motion',e.target.checked);try{localStorage.setItem('garden-motion',String(e.target.checked));}catch{}};break;case 'export':{const entries=Object.entries(state.notes);if(!entries.length){toast('Add your first note, then export your collection.');return;}const text='# My Garden notes\n\n'+entries.map(([id,n])=>{const c=getCard(id);return `## ${c?.title||'Saved thought'}\n\n${n.text}\n\nSource: ${c?.url||''}\nUpdated: ${n.updatedAt}\n`;}).join('\n');const a=document.createElement('a');const url=URL.createObjectURL(new Blob([text],{type:'text/markdown'}));a.href=url;a.download='my-garden-notes.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your notes, ready to take with you.');break;}}});
}
try{if(localStorage.getItem('garden-motion')==='true')document.documentElement.classList.add('reduce-motion');}catch{}
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();document.querySelector('#shelf-search,#collection-search')?.focus();}});
async function refresh(){try{const r=await fetch('content.json',{cache:'no-cache'});if(!r.ok)throw new Error('Source snapshot unavailable');const next=await r.json();const shelfColours={history:'#b9764f',geopolitics:'#659cae',economics:'#b69341',news:'#6495aa',finance:'#78917a',conflict:'#bc887a'};next.sections?.forEach(s=>{s.color=shelfColours[s.id]||s.color;s.readCount=next.cards?.filter(c=>c.section===s.id).length||0;});if(!Array.isArray(next.cards)||!Array.isArray(next.sections))throw new Error('Invalid content');if(!data){data=next;render();}else if(data.generatedAt!==next.generatedAt){data=next;toast('A new source snapshot is available. Reopen a shelf to see it.');}}catch(e){if(!data)document.querySelector('#app').innerHTML='<main class="empty"><h1>The library is resting.</h1><p>We couldn’t load the source snapshot. Please refresh to try again.</p><button onclick="location.reload()">Try again</button></main>';}}
await refresh();setInterval(refresh,300000);
